tape( 'the function computes the inertia between data points and their assigned centroids (row-major)', function test( t ) {
	var inertia;
	var data;

	data = ROW_MAJOR_DATA;
	inertia = dcomputeInertia( data.order, data.M, data.N, data.k, data.metric, new Float64Array( data.X ), data.LDX, new Float64Array( data.C ), data.LDC, new Int32Array( data.labels ), data.strideL );

	t.strictEqual( inertia, data.expected, 'returns expected value' );
	t.end();
});

