tape( 'the function supports all documented distance metrics', function test( t ) {
	var metrics;
	var labels;
	var out;
	var X;
	var C;
	var i;

	metrics = [ 'sqeuclidean', 'cosine', 'cityblock', 'correlation' ];

	X = new Float64Array( [ 1.0, 3.0, 5.0, 5.0, 1.5, 4.0 ] );
	C = new Float64Array( [ 1.0, 3.0, 5.0, 5.0 ] );
	labels = new Int32Array( [ 0, 1, 0 ] );

	for ( i = 0; i < metrics.length; i++ ) {
		out = dcomputeInertia( 'row-major', 3, 2, 2, metrics[ i ], X, 2, C, 2, labels, 1 );
		t.strictEqual( typeof out, 'number', 'returns a number for metric: ' + metrics[ i ] );
	}
	t.end();
});
